import csv
import io
import re


def parse_csv(raw_csv: str):
    text = raw_csv or ""
    if text.startswith("\ufeff"):
        text = text[1:]

    stream = io.StringIO(text, newline="")
    try:
        records = [list(row) for row in csv.reader(
            stream,
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=False,
            strict=False
        )]
    except csv.Error:
        records = []
        buffer = ""
        for line in text.splitlines(keepends=True):
            buffer += line
            try:
                parsed = list(csv.reader(
                    io.StringIO(buffer, newline=""),
                    delimiter=",",
                    quotechar='"',
                    doublequote=True,
                    strict=True
                ))
            except csv.Error:
                continue
            if parsed:
                records.extend([list(row) for row in parsed])
                buffer = ""
        if buffer:
            records.extend([list(row) for row in csv.reader(
                io.StringIO(buffer, newline=""),
                delimiter=",",
                quotechar='"',
                doublequote=True,
                strict=False
            )])

    expected_width = 9
    date_pattern = re.compile(r"^\s*\d{1,2}/\d{1,2}/\d{4}\s*$")
    time_pattern = re.compile(r"^\s*\d{1,2}:\d{2}(?::\d{2})?\s*$")

    start = 0
    for index, row in enumerate(records):
        if (
            len(row) >= 2
            and date_pattern.match(row[0] or "")
            and time_pattern.match(row[1] or "")
        ):
            start = index
            break
    else:
        start = 0

    records = records[start:]

    def normalize(row):
        row = ["" if value is None else str(value) for value in row]

        if len(row) == expected_width:
            return row

        if len(row) < expected_width:
            return row + [""] * (expected_width - len(row))

        url_index = None
        for i in range(5, len(row)):
            if re.match(r"^\s*(?:https?|ftp)://", row[i], re.IGNORECASE):
                url_index = i
                break

        if url_index is not None and url_index >= 7:
            middle = row[5:url_index]
            name = middle[0] if middle else ""
            description = ",".join(middle[1:]) if len(middle) > 1 else ""
            trailing = ",".join(row[url_index + 1:])
            return row[:5] + [name, description, row[url_index], trailing]

        return row[:expected_width - 1] + [",".join(row[expected_width - 1:])]

    columns = ["column_" + str(i) for i in range(1, expected_width + 1)]
    rows = [normalize(row) for row in records]
    return {"columns": columns, "rows": rows}
